import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.B8TleWq7.js";const p=JSON.parse('{"title":"Releasing Keel","description":"","frontmatter":{},"headers":[],"relativePath":"guides/releasing-keel.md","filePath":"guides/releasing-keel.md"}'),n={name:"guides/releasing-keel.md"};function o(d,e,r,h,l,g){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="releasing-keel" tabindex="-1">Releasing Keel <a class="header-anchor" href="#releasing-keel" aria-label="Permalink to &quot;Releasing Keel&quot;">​</a></h1><p>Keel is changed in its own repository and released as a Git tag. A game never edits Keel; it updates to a tag.</p><h2 id="what-is-keel-s-and-what-is-the-game-s" tabindex="-1">What is Keel&#39;s and what is the game&#39;s <a class="header-anchor" href="#what-is-keel-s-and-what-is-the-game-s" aria-label="Permalink to &quot;What is Keel&#39;s and what is the game&#39;s&quot;">​</a></h2><p><code>keel.manifest.json</code> in the Keel repo lists both. See <a href="/Keel-Docs/getting-started/what-gets-created">What gets created</a> for the full split.</p><h2 id="release-a-version" tabindex="-1">Release a version <a class="header-anchor" href="#release-a-version" aria-label="Permalink to &quot;Release a version&quot;">​</a></h2><ol><li><p><strong>Work in the Keel repo.</strong> It is also Keel&#39;s own test place: connect Script Sync there. Never edit Keel inside a game; the <code>keel-guard</code> hook refuses it.</p></li><li><p><strong>Run the unit tests</strong> (<code>[Tests] N passed, M failed</code>) and the <code>/verify</code> skill. See <a href="/Keel-Docs/guides/unit-tests">Unit tests</a>.</p></li><li><p><strong>Bump <code>VERSION</code> and add a <code>CHANGELOG.md</code> entry.</strong> Patch for fixes, minor for new features, major when a game must change its own code.</p></li><li><p><strong>Commit, then tag and push:</strong></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2.0</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tags</span></span></code></pre></div></li><li><p><strong>In each game:</strong> <code>node tools/keel.js update v0.2.0</code>. See <a href="/Keel-Docs/getting-started/update-keel">Update Keel</a>.</p></li></ol><h2 id="every-change-must-be-documented" tabindex="-1">Every change must be documented <a class="header-anchor" href="#every-change-must-be-documented" aria-label="Permalink to &quot;Every change must be documented&quot;">​</a></h2><p>A change is not finished until its documentation is updated <strong>in the same release</strong>. That covers the <code>CHANGELOG.md</code> entry, the hand-written pages (guides, tutorials, cheat sheet, FAQ, troubleshooting), the Luau header comments and <code>site/api-notes/</code> that the API Reference is generated from, and Keel&#39;s notes in <code>Docs/Systems/</code>. Run <code>npm run check</code> in <code>site/</code> before tagging.</p><p>What each kind of change needs:</p><table tabindex="0"><thead><tr><th>Change</th><th>Documentation required</th></tr></thead><tbody><tr><td><strong>New feature or module</strong></td><td>A changelog entry; a guide section or page; an API page (add it to <code>GROUPS</code> in <code>site/scripts/gen-api.mjs</code>, with a header comment and <code>api-notes/</code>); a row in the <a href="/Keel-Docs/reference/cheat-sheet">cheat sheet</a>.</td></tr><tr><td><strong>New kit</strong> (when kits arrive)</td><td>All of the above, plus its own <code>VERSION</code>, what it depends on, and how a game adds it. Kits are optional add-ons, so say clearly that a game does not get one unless it installs it.</td></tr><tr><td><strong>Deprecation</strong></td><td>The old API keeps working. Mark it deprecated in its header comment and in <code>api-notes/</code>, say what replaces it and what to change in the game, and add a <strong>Deprecated</strong> line to the changelog. Remove it only in a later <strong>major</strong> version, and say so in advance.</td></tr><tr><td><strong>Behaviour change</strong></td><td>A changelog entry saying what differs and what a game should check. Update every page that described the old behaviour.</td></tr><tr><td><strong>Breaking change</strong></td><td>A <strong>major</strong> version bump, and a <strong>Migration</strong> section in the changelog entry that tells a game exactly what to change in its own code.</td></tr><tr><td><strong>Removal</strong></td><td>Only in a major version, after at least one release that deprecated it. List it under <strong>Removed</strong> in the changelog.</td></tr><tr><td><strong>Fix</strong></td><td>A changelog entry. Update any page or troubleshooting item that described the bug or its workaround.</td></tr></tbody></table><h3 id="changelog-entries" tabindex="-1">Changelog entries <a class="header-anchor" href="#changelog-entries" aria-label="Permalink to &quot;Changelog entries&quot;">​</a></h3><p>Group each version&#39;s entry under these headings, leaving out any that do not apply: <strong>Added</strong>, <strong>Changed</strong>, <strong>Deprecated</strong> (still works, but update your game), <strong>Removed</strong>, <strong>Fixed</strong>, <strong>Migration</strong> (what a game must do). Write them for someone deciding whether to run <code>update</code>.</p><h3 id="deprecation-example" tabindex="-1">Deprecation example <a class="header-anchor" href="#deprecation-example" aria-label="Permalink to &quot;Deprecation example&quot;">​</a></h3><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 0.3.0</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Added</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> `Net.stream`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> for large replaceable payloads.</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Deprecated</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> `Net.unreliable`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> is now </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`Net.stream`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">. </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`Net.unreliable`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> still works and logs a warning once; switch to </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`Net.stream`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> in your Shared/Net list.</span></span></code></pre></div><h2 id="behaviour-to-rely-on" tabindex="-1">Behaviour to rely on <a class="header-anchor" href="#behaviour-to-rely-on" aria-label="Permalink to &quot;Behaviour to rely on&quot;">​</a></h2><ul><li><code>update</code> replaces whole owned folders, so a file Keel dropped disappears from the game.</li><li>Hashes ignore line endings, so a checkout on another machine does not look like an edit.</li><li>Nothing at runtime reads the version; it lives only in <code>keel.json</code> and <code>VERSION</code>.</li><li><code>keel.js new</code> and <code>update</code> take the newest <code>v*</code> tag when you give none or say <code>latest</code>.</li></ul><h2 id="trying-a-change-before-tagging" tabindex="-1">Trying a change before tagging <a class="header-anchor" href="#trying-a-change-before-tagging" aria-label="Permalink to &quot;Trying a change before tagging&quot;">​</a></h2><p><code>keel.js</code> accepts <code>--from &lt;path&gt;</code> to use a local Keel checkout instead of cloning from GitHub:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/keel.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> latest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../Keel</span></span></code></pre></div><h2 id="this-documentation" tabindex="-1">This documentation <a class="header-anchor" href="#this-documentation" aria-label="Permalink to &quot;This documentation&quot;">​</a></h2><p>These docs live in <code>site/</code> in the Keel repo. The API pages are regenerated from the source on every build, and the changelog page from <code>CHANGELOG.md</code>, so a release needs no extra docs step beyond updating the hand-written pages when behaviour changed. See <code>site/README.md</code>.</p>',21)])])}const k=t(n,[["render",o]]);export{p as __pageData,k as default};
